package com.dtm.platform.controller;import com.dtm.platform.repository.*;import com.dtm.platform.entity.*;import com.dtm.platform.exception.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.beans.factory.annotation.Value;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController {
 private final UserRepository users;private final RoleRepository roles;private final PasswordEncoder passwords;private final JwtEncoder encoder;@Value("${app.jwt-issuer}")String issuer;
 public AuthController(UserRepository users,RoleRepository roles,PasswordEncoder passwords,JwtEncoder encoder){this.users=users;this.roles=roles;this.passwords=passwords;this.encoder=encoder;}
 public record Login(@NotBlank @Email String email,@NotBlank @Size(max=200) String password){}
 @PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody Login input){throw new ApiException(HttpStatus.GONE,"Use mobile OTP sign-in.");}
 @GetMapping("/me") public Map<String,Object> me(@AuthenticationPrincipal Jwt jwt){String display=jwt.getClaimAsString("displayName");return Map.of("email","","displayName",display==null?"Administrator":display,"roles",jwt.getClaimAsStringList("roles"),"authMethod","otp","mode","spring-jwt");}
 @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) public void logout(){}
 public record CreateUser(@Email @NotBlank String email,@NotBlank @Size(min=14,max=64) String password,@Pattern(regexp="ADMIN|EDITOR") String role){}
 @PostMapping("/users") @PreAuthorize("hasRole('ADMIN')") public Map<String,Object> create(@Valid @RequestBody CreateUser in){if(in.password().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new IllegalArgumentException("Password exceeds 72 UTF-8 bytes");User u=new User();u.email=in.email().toLowerCase(Locale.ROOT);u.passwordHash=passwords.encode(in.password());u.roles.add(roles.findById(in.role()).orElseThrow());users.save(u);return Map.of("id",u.id,"email",u.email,"roles",List.of(in.role()));}
}
